// src/index.ts
function checkSupport() {
  const missing = [];
  if (typeof window === "undefined" || typeof document === "undefined") {
    return { ok: false, missing: ["browser"] };
  }
  try {
    const canvas = document.createElement("canvas");
    const gl = canvas.getContext("webgl2");
    if (!gl) {
      missing.push("WebGL2");
    } else {
      const floatTarget = gl.getExtension("EXT_color_buffer_float");
      if (!floatTarget) missing.push("EXT_color_buffer_float");
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    }
  } catch {
    missing.push("WebGL2");
  }
  return { ok: missing.length === 0, missing };
}
function isWaterSupported() {
  return checkSupport().ok;
}
function createWaterScene(container, options = {}) {
  const host = typeof container === "string" ? document.querySelector(container) : container;
  if (!host) throw new Error(`[threejs-water] \u627E\u4E0D\u5230\u5BB9\u5668\uFF1A${String(container)}`);
  return new WaterScene(host, options);
}

// examples/hexo/main.ts
var stage = document.getElementById("stage");
var boot = document.getElementById("boot");
var bootLabel = document.getElementById("boot-label");
var bootFill = document.getElementById("boot-fill");
if (!isWaterSupported()) {
  boot.dataset.state = "error";
  bootLabel.textContent = "\u5F53\u524D\u6D4F\u89C8\u5668\u7F3A\u5C11 WebGL2 \u6D6E\u70B9\u6E32\u67D3\u652F\u6301";
} else {
  const scene = createWaterScene(stage, {
    assetBase: "./assets/",
    settings: { preset: "Three.js Sky Package" },
    panel: { title: "Water Scene" }
  });
  scene.on("progress", ({ value, label }) => {
    bootFill.style.width = `${Math.round(value * 100)}%`;
    bootLabel.textContent = label;
  });
  scene.once("ready", () => scene.resetCamera());
  scene.on("ready", () => {
    boot.dataset.state = "ready";
  });
  scene.on("error", (error) => {
    boot.dataset.state = "error";
    bootLabel.textContent = `${error.code}: ${error.message}`;
    console.error("[threejs-water]", error);
  });
  window.scene = scene;
}
